def choose_num(x, y):
    if x > y:
        return -1

    # Start from the largest number in range and go down by 2 until we find an even number
    start = y if y % 2 == 0 else y - 1
    for num in range(start, max(x-1, -float('inf')), -2):
        if x <= num:
            return num

    # If no even number is found (shouldn't happen with the logic above unless start < x)
    return -1
